<script setup>
import{onMounted,ref}from'vue'
import {Dropdown as ADropdown,Menu as AMenu,MenuItem as AMenuItem} from 'ant-design-vue'
import{api,download}from'../api'
const logs=ref([]),error=ref(''),busy=ref(false),total=ref(0),page=ref(1),size=ref(20),options=ref({users:[],actions:[],resources:[]})
const filters=ref({user_id:'',actor:'',resource:'',object_id:'',action:'',result:'',start:'',end:''})
const exportQuery=ref(''),queried=ref(false),success=ref('')
function filterQuery(){const query=new URLSearchParams();for(const [key,value]of Object.entries(filters.value)){if(value)query.set(key,['start','end'].includes(key)?new Date(value).toISOString():value)}return query}
async function load(reset=false){if(reset)page.value=1;busy.value=true;error.value='';try{const query=filterQuery(),selected=query.toString();query.set('page',page.value);query.set('page_size',size.value);const data=await api('/api/audits?'+query);logs.value=data.items;total.value=data.total;exportQuery.value=selected;queried.value=true}catch(e){error.value=e.message;queried.value=false}finally{busy.value=false}}
async function exportLogs(format){busy.value=true;error.value='';success.value='';try{const query=new URLSearchParams(exportQuery.value);query.set('format',format);await download('/api/audits/export?'+query,`审计日志.${format}`);success.value='已导出最近一次成功查询的全部匹配结果，不受当前页码影响；导出动作另行记入审计日志'}catch(e){error.value=e.message}finally{busy.value=false}}
function clear(){filters.value={user_id:'',actor:'',resource:'',object_id:'',action:'',result:'',start:'',end:''};load(true)}
onMounted(async()=>{try{options.value=await api('/api/audits/options');await load()}catch(e){error.value=e.message}})
const names={success:'成功',failure:'失败',denied:'拒绝访问',unknown:'旧记录：结果未知'}
</script>
<template><div class="page-stack"><div class="page-intro"><div><h2>审计日志</h2><p>按操作者、时间、对象和结果追踪关键操作；导出范围与最近一次查询一致</p></div><div class="toolbar"><button class="secondary-button" :disabled="busy" @click="load()">刷新</button><ADropdown :trigger="['click']"><button class="primary-button" :disabled="busy||!queried">导出查询结果 ▾</button><template #overlay><AMenu><AMenuItem @click="exportLogs('csv')">CSV 表格</AMenuItem><AMenuItem @click="exportLogs('json')">JSON 数据</AMenuItem></AMenu></template></ADropdown></div></div><form class="card filter-panel" @submit.prevent="load(true)"><div class="basic-filters"><label class="field">用户<select v-model="filters.user_id" class="select"><option value="">全部用户</option><option v-for="u in options.users" :key="u.id" :value="u.id">{{u.name}}（{{u.username}}）</option></select></label><label class="field">动作<select v-model="filters.action" class="select"><option value="">全部动作</option><option v-for="a in options.actions" :key="a">{{a}}</option></select></label><label class="field">结果<select v-model="filters.result" class="select"><option value="">全部结果</option><option v-for="(name,key) in names" :key="key" :value="key">{{name}}</option></select></label><div class="toolbar"><button class="primary-button" :disabled="busy">{{busy?'查询中…':'查询'}}</button><button type="button" class="secondary-button" :disabled="busy" @click="clear">重置</button></div></div><details class="advanced-filters"><summary>更多筛选（时间、对象、账号）</summary><div><label class="field">显示名 / 账号包含<input v-model="filters.actor" class="input" placeholder="包括未登录失败记录"/></label><label class="field">开始时间（本地）<input v-model="filters.start" class="input" type="datetime-local"/></label><label class="field">结束时间（本地）<input v-model="filters.end" class="input" type="datetime-local"/></label><label class="field">对象类型<select v-model="filters.resource" class="select"><option value="">全部对象</option><option v-for="r in options.resources" :key="r">{{r}}</option></select></label><label class="field">对象 ID<input v-model="filters.object_id" class="input" placeholder="例如文档或任务 ID"/></label></div></details></form><div v-if="error" class="error-banner">{{error}}</div><div v-if="success" class="success-banner">{{success}}</div><section class="card"><div class="card-header"><h3>查询结果 · 共 {{total}} 条</h3><select v-model="size" class="select page-size" @change="load(true)"><option :value="20">每页 20 条</option><option :value="50">每页 50 条</option><option :value="100">每页 100 条</option></select></div><div class="card-body table-wrap"><table><thead><tr><th>时间</th><th>用户</th><th>动作</th><th>对象 / ID</th><th>结果</th><th>详情</th></tr></thead><tbody><tr v-for="item in logs" :key="item.id"><td>{{new Date(item.created_at).toLocaleString()}}</td><td>{{item.actor}}<br/><small>{{item.username||'历史记录 / 匿名'}}</small></td><td>{{item.action}}</td><td>{{item.resource}}<br/>{{item.object_id||'—'}}</td><td><span class="badge" :class="item.result==='success'?'green':item.result==='unknown'?'amber':'red'">{{names[item.result]}}</span><small v-if="item.status_code"> HTTP {{item.status_code}}</small></td><td>{{item.detail}}<br/><small>{{item.source}}</small></td></tr></tbody></table><div v-if="!logs.length" class="empty">没有符合筛选条件的审计记录</div></div><div class="pagination"><button class="secondary-button" :disabled="page<=1||busy" @click="page--;load()">上一页</button><span>第 {{page}} / {{Math.max(1,Math.ceil(total/size))}} 页</span><button class="secondary-button" :disabled="page*size>=total||busy" @click="page++;load()">下一页</button></div></section></div></template>
<style scoped>.filter-panel{padding:18px 20px}.basic-filters{display:grid;grid-template-columns:repeat(3,minmax(0,1fr)) auto;gap:14px;align-items:end}.advanced-filters{margin-top:14px;font-size:12px;color:var(--muted)}.advanced-filters summary{cursor:pointer}.advanced-filters>div{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px;margin-top:16px}.pagination{display:flex;align-items:center;justify-content:flex-end;gap:15px;padding:14px 20px;font-size:12px}.page-size{width:150px}.table-wrap table{min-width:900px}td{font-size:12px}td small{color:var(--muted)}@media(max-width:1100px){.basic-filters,.advanced-filters>div{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:600px){.basic-filters{grid-template-columns:1fr 1fr}.basic-filters>.field:first-child,.basic-filters>.toolbar{grid-column:1/-1}.advanced-filters>div{grid-template-columns:1fr}.filter-panel{padding:16px}}</style>
